edits.before:
constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
  super(element, config)

  this._calendar = null
  this._isShown = false

  this._initCalendar()
}

  this._setupDismiss()

  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()
}

edits.after:
  this._setupDismiss()

  // Hide datepicker when losing focus unless focus is moving to the calendar
  this._onFocusout = (event: FocusEvent) => {
    if (!this._isShown) {
      return
    }
    const calendarMainElement = this._calendar?.context?.mainElement
    if (calendarMainElement && calendarMainElement.contains(event.relatedTarget as Node)) {
      return
    }
    this.hide()
  }

  EventHandler.on(this._element, 'focusout', this._onFocusout)

  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()
}

edits.before:
  if (this._onTriggerClick) {
    EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
  }

  if (this._calendar) {
    this._calendar.destroy()
  }

  this._calendar = null
  super.dispose()
}

edits.after:
  if (this._onTriggerClick) {
    EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
  }

  if (this._onFocusout) {
    EventHandler.off(this._element, 'focusout', this._onFocusout)
    this._onFocusout = null
  }

  if (this._calendar) {
    this._calendar.destroy()
  }

  this._calendar = null
  super.dispose()
}
